import org.junit.jupiter.api.parallel.Resources;

/** Whole-domain answers come from the base alone, so they may only serve a snapshot the base fully represents. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbAdjacencyNodeDomainTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI P = F.createIRI("http://example.org/node-domain/p");
	private static final IRI A = F.createIRI("http://example.org/node-domain/a");
	private static final IRI B = F.createIRI("http://example.org/node-domain/b");
	private static final IRI N = F.createIRI("http://example.org/node-domain/n");

	@TempDir
	File dataDir;

	private String previousSynchronousMaintenance;
	private String previousSynopsis;
	private SailRepository repo;

	@AfterEach
	void tearDown() {
		try {
			if (repo != null) {
				repo.shutDown();
			}
		} finally {
			restore(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY, previousSynchronousMaintenance);
			restore("rdf4j.lmdb.directAdjacency.synopsis.enabled", previousSynopsis);
		}
	}

	@Test
	void aPendingCommitKeepsTheBaseDomainFromAnsweringItsSnapshot() throws Exception {
		previousSynchronousMaintenance = System
				.getProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY);
		previousSynopsis = System.getProperty("rdf4j.lmdb.directAdjacency.synopsis.enabled");
		// Commits then reach the index through pending tables and the apply queue.
		System.setProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY, "false");
		System.setProperty("rdf4j.lmdb.directAdjacency.synopsis.enabled", "true");
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repo = new SailRepository(sail);
		repo.init();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(A, P, B);
			connection.add(B, P, A);
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		LmdbSailStore backing = sail.getBackingStore();
		LmdbDirectAdjacencyStore direct = backing.directAdjacencyStore();
		// A fresh base holds every committed row, so no overlay generation marks the next snapshot as changed.
		assertThat(direct.rebuildNowForTest()).isTrue();
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		direct.pauseApplierForTest(true);
		try {
			try (RepositoryConnection connection = repo.getConnection()) {
				// n's first edges, in both directions, stay in a pending table.
				connection.begin();
				connection.add(N, P, A);
				connection.add(A, P, N);
				connection.commit();
			}
			long n = backing.valueStore().getId(N);
			try (LmdbAdjacencyReadView view = direct.acquire(backing.getTripleStore().getDataRevision())) {
				NativeLmdbQuerySource.NodeDomainPresence subjects = direct.nodeDomainPresence(view, true, true);
				if (subjects != null) {
					assertThat(subjects.contains(n)).as("a subject committed in this snapshot").isTrue();
				}
				NativeLmdbQuerySource.NodeDomainSynopsis objects = direct.nodeDomainSynopsis(view, false, true);
				if (objects != null) {
					assertThat(objects.contains(n)).as("an object committed in this snapshot").isTrue();
				}
				NativeLmdbQuerySource.NodeDomainIntersection both = direct.nodeDomainIntersection(view, true, false,
						true);
				if (both != null) {
					assertThat(both.contains(n)).as("a node that is both subject and object in this snapshot")
							.isTrue();
				}
			}
		} finally {
			direct.pauseApplierForTest(false);
		}
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}
}
